import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);
        long left = Long.parseLong(parts[2]);
        long right = Long.parseLong(parts[3]);

        long totalCells = n * m;

        if (totalCells % 2 == 0) {
            long span = right - left + 1;
            long evenCount = span / 2;
            if (span % 2 == 0 && left % 2 == 0) {
                evenCount++;
            }
            long oddCount = span - evenCount;

            Map<Long, Long> memo0 = new HashMap<>();
            Map<Long, Long> memo1 = new HashMap<>();

            pw.println(computeResult(totalCells, 0, evenCount, oddCount, memo0, memo1));
        } else {
            long answer = powMod(span(right - left + 1), totalCells);
            pw.println(answer);
        }

        pw.flush();
        pw.close();
    }

    static long computeResult(long n, int x, long even, long odd, Map<Long, Long> cache0, Map<Long, Long> cache1) {
        if (x == 0) {
            if (cache0.containsKey(n)) return cache0.get(n);
            if (n == 1) return even;
            if (n == 2) return (even * even + odd * odd) % 998244353;
            long a = computeResult(n / 2, 0, even, odd, cache0, cache1);
            long b = computeResult(n - n / 2, 0, even, odd, cache0, cache1);
            long c = computeResult(n / 2, 1, even, odd, cache0, cache1);
            long d = computeResult(n - n / 2, 1, even, odd, cache0, cache1);
            long res = (a * b + c * d) % 998244353;
            cache0.put(n, res);
            return res;
        } else {
            if (cache1.containsKey(n)) return cache1.get(n);
            if (n == 1) return odd;
            if (n == 2) return (even * odd + odd * even) % 998244353;
            long a = computeResult(n / 2, 0, even, odd, cache0, cache1);
            long b = computeResult(n - n / 2, 1, even, odd, cache0, cache1);
            long c = computeResult(n / 2, 1, even, odd, cache0, cache1);
            long d = computeResult(n - n / 2, 0, even, odd, cache0, cache1);
            long res = (a * b + c * d) % 998244353;
            cache1.put(n, res);
            return res;
        }
    }

    static long powMod(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % 998244353;
            base = (base * base) % 998244353;
            exp >>= 1;
        }
        return result;
    }
